pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x1);
        address to = address(0x2);
        address[] memory tos = new address[](1);
        tos[0] = to;
        // Call transfer with a caddress that is an EOA or contract without transferFrom support
        address fakeToken = address(0xdead);
        bool ok;
        try c.transfer(from, fakeToken, tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference version reverts (ok == false), buggy version returns true (ok == true)
        // We assert that the call reverts, which holds for reference but fails for buggy
        assertTrue(!ok);
    }
}

