contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address from = address(0x123);
        address token = address(0x456);
        address[] memory tos = new address[](1);
        tos[0] = address(0x789);
        uint256 value = 100;
        // The token contract doesn't implement transferFrom -> will revert
        bool ok;
        try c.transfer(from, token, tos, value) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference version: require(_s) triggers revert, so ok == false
        // Modified version: no require, so call silently succeeds, ok == true
        assertTrue(!ok);
    }
}

