pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that returns false on transferFrom
        Token token = new Token();
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 100;

        // Attempt the transfer; the reference contract should revert because token.transferFrom returns false
        // The buggy contract does not check the return value, so it will succeed
        bool ok;
        try c.transfer(from, address(token), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Token {
    function transferFrom(address, address, uint256) public pure returns (bool) {
        return false;
    }
}

